--
-- Canvas schema parity: secondary indexes for the new Canvas tables.
--
-- Same source as the table migrations; index names follow the Rails
-- index_<table>_on_<columns> convention (they are Rails' own names where a
-- migration spelled one out). CONCURRENTLY / algorithm options are dropped
-- because sqlx applies each file inside one transaction.
--
-- ICU collations, mirroring Canvas' config/initializers/postgresql_adapter.rb
-- (created there at boot; created here because the indexes below use them).
CREATE COLLATION IF NOT EXISTS public."und-u-kn-true" (LOCALE = 'und-u-kn-true', PROVIDER = icu, DETERMINISTIC = false);

